/* Flash cards USMLE: Behavioral Science (417 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["behavioral-science"] = [{"name":"Development","cards":[["n9u1fm6vj","What is the APGAR score used for?","Assessment of a newborn at 1 and 5 minutes after birth (and 10 minutes if low).","Avaliar o recém-nascido."],["vv7rlu13u","What are the five components of the APGAR score?","Appearance (color), Pulse, Grimace (reflex irritability), Activity (muscle tone), Respiration. Each scored 0-2.","Cor, pulso, careta, tônus, respiração."],["j4rxr5ug6","What APGAR score range is considered normal?","7-10. A score below 7 may require intervention (e.g., stimulation, resuscitation).","7 a 10."],["1czmopjmb","What defines low birth weight?","Birth weight less than 2500 g (5.5 lb).","Menos de 2.500 g."],["1eb90kexr","What are the main causes of low birth weight?","Prematurity and intrauterine growth restriction.","Prematuridade e restrição de crescimento."],["tmv0l83qs","What complications are associated with low birth weight?","Infections, respiratory distress syndrome, necrotizing enterocolitis, intraventricular hemorrhage, persistent fetal circulation, sudden infant death syndrome; increased mortality.","Infecções, SDR, enterocolite."],["cms9a21h1","What is the Moro reflex and when does it disappear?","Hang on for life reflex: abduct and extend arms when startled, then draw them together. Disappears by about 3-4 months.","Reflexo de Moro some aos 3-4 meses."],["1m7t95hit","What is the rooting reflex?","Infant turns head toward the side of cheek stroked, searching for the nipple; disappears around 4 months.","Vira a cabeça buscando o peito."],["dozszh1uk","What is the sucking reflex?","Infant sucks when the roof of the mouth is touched; disappears around 4 months.","Suga ao tocar o palato."],["kwiz0ngj5","What is the palmar grasp reflex?","Infant grasps objects placed in the palm; disappears by about 6 months.","Agarra o que toca a palma."],["1841bi7r8","What is the plantar (Babinski) reflex in infants?","Dorsiflexion of the large toe and fanning of other toes with plantar stimulation; normal until about 1 year.","Babinski normal até 1 ano."],["177zxfml2","What is the Galant reflex?","Stroking along one side of the spine while the newborn is prone causes lateral flexion of the lower body toward the stimulated side; disappears around 4 months.","Flexão lateral ao tocar a coluna."],["1k7qhhw16","What does persistence or reappearance of primitive reflexes suggest?","Frontal lobe lesion or other CNS pathology (e.g., cerebral palsy).","Lesão do lobo frontal."],["zk5a4x16n","At what age does an infant typically hold head up when prone?","About 2-3 months (head steady by 4 months).","2 a 3 meses."],["o9ejod5gq","At what age does a child sit without support?","About 6 months.","6 meses."],["9k08op1ey","At what age does a child roll over (front to back, then back to front)?","About 4-5 months.","4 a 5 meses."],["1uk8fmqsz","At what age does a child crawl and pull to stand?","About 8-10 months.","8 a 10 meses."],["wjjg9ezzd","At what age does a child walk independently?","About 12 months (cruising around 10-12 months).","12 meses."],["jm61pglv1","At what age can a child climb stairs and run?","About 18 months (walks upstairs with help); runs well and kicks a ball around 2 years.","18 meses a 2 anos."],["1ersitf19","At what age can a child pedal a tricycle?","About 3 years.","3 anos."],["1rbhncxm7","At what age can a child hop on one foot?","About 4 years.","4 anos."],["kjhbfk4md","When does a social smile appear?","About 2 months.","2 meses."],["113w5biyk","When does stranger anxiety develop?","About 6 months.","6 meses."],["iud071wys","When does separation anxiety typically peak?","About 9-18 months (begins around 9 months).","9 a 18 meses."],["1dn05lj1p","When does a child typically say 'mama/dada' nonspecifically and specifically?","Nonspecific around 6-9 months; specific at about 10-12 months.","6-9 meses; específico aos 10-12."],["tmhuy8dqx","How many words does a typical 1-year-old use?","About 1-3 words.","1 a 3 palavras."],["jgodx8lx6","How many words and what phrases does a typical 2-year-old use?","About 200 words and 2-word phrases.","200 palavras e frases de 2."],["1o67hyr1p","How many words does a typical 3-year-old use and how intelligible?","About 900 words, 3-word sentences, mostly intelligible to strangers (75%).","900 palavras; 75% compreensível."],["n7yi3b18e","When does a child speak in complete sentences and tell stories?","About 4 years (100% intelligible).","4 anos."],["k9f23y1sd","When does a child use a pincer grasp?","About 9-10 months.","9 a 10 meses."],["63ml7ksv3","When can a child stack 2 blocks? 6 blocks? 9 blocks?","2 blocks at 15 months, 6 blocks at 2 years, 9 blocks at 3 years. (Rule: age in years x 3).","Idade x 3."],["ps2td51mj","When can a child copy a circle, cross, square, and triangle?","Circle at 3, cross at 4, square at 4-5, triangle at 5 years.","Círculo 3, cruz 4, quadrado 4-5, triângulo 5."],["tnhxes13w","When does a child develop object permanence?","About 9 months (begins 6-9 months).","9 meses."],["1j9sq4f1y","When does a child engage in parallel play?","About 2 years (play alongside other children).","2 anos."],["1sk3rcv2g","When does a child engage in cooperative play?","About 4 years (plays with other children, has imaginary friends).","4 anos."],["123pc0ijg","When does core gender identity develop?","About 3 years.","3 anos."],["1wcv20xa8","When is toilet training usually achieved?","About 2.5-3 years for daytime; nighttime dryness later.","2,5 a 3 anos."],["1a0xb0611","What does 'rapprochement' refer to in toddler development?","About 18-24 months, child moves away from caregiver but returns for reassurance.","Volta ao cuidador para se assegurar."],["1771bhr1i","What is the most common cause of developmental delay that is preventable?","Fetal alcohol spectrum disorder (and lead poisoning environmentally).","Síndrome alcoólica fetal."],["qlj7in1x9","What are red flags in child development warranting evaluation?","No babbling by 12 months, no single words by 16 months, no 2-word phrases by 24 months, any loss of skills at any age.","Sem palavras ou perda de habilidades."],["1bvbe8k12","What changes in sleep occur in the elderly?","Decreased REM and slow-wave sleep, increased sleep latency, more early awakenings.","Menos sono profundo e REM."],["be4d9o140","What sexual changes occur with normal aging?","Men: slower erection/ejaculation, longer refractory period. Women: vaginal shortening, thinning, dryness. Sexual interest does not decrease.","Respostas sexuais mais lentas."],["1wpsiqgnx","What happens to intelligence with normal aging?","Intelligence does not decrease; learning new skills may take longer.","Não diminui."],["2e7nt31r6","Which psychiatric problem is common in the elderly and often missed?","Depression (also increased suicide risk, especially in older white men).","Depressão."],["yo18ro169","Is cognitive decline a normal part of aging?","Mild slowing of processing is normal, but significant memory loss interfering with function is not normal (consider dementia).","Não é normal."],["xqwwcoguc","What happens to muscle mass, bone, and kidney function with aging?","Decreased muscle mass and bone density (sarcopenia, osteoporosis), decreased GFR, more body fat.","Menos músculo, osso e filtração."],["t7cf3hb8v","How does aging affect drug metabolism?","Decreased hepatic and renal clearance and more body fat increase half-lives of lipid-soluble drugs; start low, go slow.","Comece com dose baixa."],["lgyt6yfi4","What are Erikson's stages: trust vs mistrust?","Infancy (0-1 year): consistent care leads to trust.","Bebê: confiança."],["1p0jop91a","Erikson stage: autonomy vs shame and doubt?","Toddler (1-3 years): developing control and independence.","1-3 anos: autonomia."],["nhoejdzxr","Erikson stage: initiative vs guilt?","Preschool (3-6 years): exploring and taking initiative.","3-6 anos: iniciativa."],["1cmv6gq1v","Erikson stage: industry vs inferiority?","School age (6-12 years): competence through learning and achievement.","Escola: produtividade."],["1rl20267y","Erikson stage: identity vs role confusion?","Adolescence: developing a sense of self and personal identity.","Adolescente: identidade."],["1do0emm1f","Erikson stage: intimacy vs isolation?","Young adulthood: forming close relationships.","Adulto jovem: intimidade."],["ciirep803","Erikson stage: generativity vs stagnation?","Middle adulthood: contributing to the next generation (work, parenting).","Meia-idade: generatividade."],["jst54p1d4","Erikson stage: integrity vs despair?","Late adulthood: reflecting on life with satisfaction or regret.","Idoso: integridade."],["1gm3e7ynf","Piaget: sensorimotor stage?","Birth to 2 years: learning through senses and actions; object permanence develops.","0-2 anos: sentidos e ação."],["14xr1g51t","Piaget: preoperational stage?","2-7 years: symbolic thinking and language, egocentrism, no conservation.","2-7 anos: simbólico e egocêntrico."],["18iw1051g","Piaget: concrete operational stage?","7-11 years: logical thinking about concrete objects, conservation, reversibility.","7-11 anos: lógica concreta."],["4hvkuhxvs","Piaget: formal operational stage?","12 years and older: abstract reasoning and hypothetical thinking.","12+: pensamento abstrato."],["k5wlxqwwj","What is Tanner staging used for?","Assessing sexual maturity (pubic hair, breast, genital development) from stage 1 (prepubertal) to 5 (adult).","Maturidade sexual."],["19r08n57b","What is usually the first sign of puberty in girls?","Thelarche (breast budding), typically around 8-13 years.","Broto mamário."],["ktatol1ke","What is usually the first sign of puberty in boys?","Testicular enlargement, typically around 9-14 years.","Aumento testicular."],["148z8843i","Order of puberty in girls?","Thelarche, pubarche, growth spurt, menarche (about 2-3 years after thelarche).","Mamas, pelos, estirão, menarca."],["tbofid3qk","When does the growth spurt occur in boys vs girls?","Girls: early puberty (before menarche). Boys: later in puberty (Tanner 3-4).","Meninas antes; meninos depois."],["1omdv771f","What defines precocious puberty?","Secondary sexual characteristics before age 8 in girls or 9 in boys.","Antes de 8 nas meninas ou 9 nos meninos."],["khjlqnlnm","What defines delayed puberty?","No breast development by 13 in girls or no testicular enlargement by 14 in boys.","Sem mamas aos 13 ou testículos aos 14."],["6qrx8fvfx","What are common causes of failure to thrive?","Inadequate caloric intake (most common, often psychosocial), malabsorption, increased metabolic demands, chronic disease.","Pouca ingestão calórica."],["13jjhn71m","What is the typical weight gain pattern in infancy?","Birth weight doubles by about 4-5 months and triples by 1 year.","Dobra aos 4-5 meses; triplica com 1 ano."],["24d8fe1df","When do newborns regain their birth weight?","By about 10-14 days.","10 a 14 dias."],["z525jo188","What are the developmental features of a child with neglect?","Failure to thrive, poor hygiene, developmental delay, withdrawal, poor social skills.","Atraso e higiene ruim."],["1p813yi1p","What is the most common form of child maltreatment?","Neglect.","Negligência."],["1dv5bb116","What findings suggest physical child abuse?","Injuries inconsistent with history, posterior rib fractures, metaphyseal corner fractures, multiple fractures at different stages, cigarette burns, subdural hematomas, retinal hemorrhages.","Fraturas sem explicação."],["1s6xaff1c","What injuries suggest abusive head trauma (shaken baby)?","Subdural hematomas, retinal hemorrhages, and encephalopathy, often without external signs.","Hematoma subdural e hemorragia retiniana."],["1x4drufo7","What is the physician's duty when child abuse is suspected?","Report to child protective services (mandatory reporting); ensure the child's safety, hospitalize if needed.","Notificar o conselho tutelar."],["14nwv6s1v","What is the typical age of most victims of fatal child abuse?","Usually under 3 years (infants are at the highest risk).","Menores de 3 anos."],["1dvrwegl0","What signs suggest child sexual abuse?","STIs, genital/anal trauma, age-inappropriate sexual knowledge or behavior, recurrent UTIs; peak age 9-12 years.","IST e trauma genital."],["yi6u4e10i","What is the leading cause of death in infants (<1 year) in the US?","Congenital malformations.","Malformações congênitas."],["182cm8f1y","What is the leading cause of death in children and adolescents (1-14 years)?","Unintentional injuries.","Acidentes."],["l7i0sarar","What is the leading cause of death in adolescents and young adults (15-34 years)?","Unintentional injuries (followed by suicide and homicide).","Acidentes."],["1k9nov61d","What is the leading cause of death in adults over 65 in the US?","Heart disease (followed by cancer).","Doença cardíaca."],["yj2s92zw3","What measures reduce sudden infant death syndrome risk?","Back to sleep, firm mattress, no soft bedding, room-sharing without bed-sharing, pacifier at sleep, avoid smoke exposure, breastfeeding.","Dormir de barriga para cima."],["1tkqr2vgg","What risk factors increase sudden infant death syndrome?","Prone sleeping, soft bedding, overheating, maternal smoking, prematurity, low birth weight, bed-sharing.","Bruços, fumo, prematuridade."]]},{"name":"Epidemiology & Biostatistics","cards":[["3rsjo31ai","What is a cross-sectional study?","Collects data from a group at one point in time to assess frequency of disease and exposures (prevalence). Asks: what is happening?","Retrato num único momento."],["jucppt1oh","What measure does a cross-sectional study yield?","Disease prevalence; can show associations but not causality.","Prevalência."],["13hque21f","What is a case-control study?","Compares a group with disease to a group without disease, looking back for prior exposure. Asks: what happened?","Parte dos casos e olha para trás."],["xpfdegjj9","What measure does a case-control study yield?","Odds ratio (OR).","Odds ratio."],["u1xoyxzlf","What is a cohort study?","Compares a group with an exposure to a group without, following them for disease incidence.","Segue expostos ao longo do tempo."],["h6uzlamtl","Prospective vs retrospective cohort study?","Prospective: follows exposed and unexposed groups forward in time. Retrospective: uses past records to look at exposure and later outcomes.","Futuro vs dados passados."],["138ynxn1j","What measure does a cohort study yield?","Relative risk (RR).","Risco relativo."],["aelcdc1u1","What is an ecological study?","Compares frequency of disease and exposure between populations (not individuals); used to generate hypotheses.","Analisa grupos, não indivíduos."],["1xwzh0l9h","What is the ecological fallacy?","Applying population-level associations to individuals.","Grupo não vale para o indivíduo."],["sxcvchzkw","What is a twin concordance study?","Compares the frequency of a disease in monozygotic vs dizygotic twins to assess heritability vs environment.","Gêmeos: genética vs ambiente."],["1k58odoma","What is an adoption study?","Compares adopted children with biological vs adoptive parents to estimate the role of genetics vs environment.","Separa genes do ambiente."],["pndmq12b0","What is a randomized controlled trial and why is it the gold standard?","Participants are randomly assigned to interventions; randomization balances confounders, giving the highest-quality evidence for causality.","Sorteio elimina confusão."],["oo8hmcpj5","What is a crossover study?","Each subject receives both treatments in sequence (with washout), acting as their own control.","Cada um recebe os dois."],["1jagxm1ep","What is a meta-analysis?","Pools data from several similar studies to increase power; limited by the quality and heterogeneity of included studies.","Junta vários estudos."],["b6oa091xo","What is phase I of a clinical trial?","Small number of healthy volunteers (or patients for toxic drugs); assesses safety, toxicity, pharmacokinetics, pharmacodynamics.","Segurança em poucos sadios."],["1ft4wdc4g","What is phase II of a clinical trial?","Small number of patients with the disease; assesses efficacy, optimal dosing, and adverse effects.","Eficácia e dose."],["1c5m87dxy","What is phase III of a clinical trial?","Large number of patients randomly assigned to new drug vs standard of care or placebo; compares effectiveness. Needed for approval.","Compara com o padrão."],["7cw7drrth","What is phase IV of a clinical trial?","Postmarketing surveillance after approval; detects rare or long-term adverse effects.","Vigilância pós-venda."],["1x3ungw1u","Mnemonic for clinical trial phases?","Does the drug SWIM? Safety, Works?, Improvement?, Market.","Fases: segurança, eficácia, comparação, pós-mercado."],["19b4i9u1f","Formula for sensitivity?","TP / (TP + FN). Proportion of people with disease who test positive.","VP / (VP + FN)."],["5cgxrfdby","Formula for specificity?","TN / (TN + FP). Proportion of people without disease who test negative.","VN / (VN + FP)."],["7zkfpwj9f","What is a high-sensitivity test useful for?","Screening; a negative result rules out disease (SN-N-OUT).","Descartar doença."],["1qttbnh1a","What is a high-specificity test useful for?","Confirmation; a positive result rules in disease (SP-P-IN).","Confirmar doença."],["zr2ars3w0","Formula for positive predictive value?","TP / (TP + FP). Probability that a positive test truly has disease.","VP / (VP + FP)."],["u1gegw19c","Formula for negative predictive value?","TN / (TN + FN). Probability that a negative test truly lacks disease.","VN / (VN + FN)."],["2c48e8how","How does prevalence affect PPV and NPV?","Higher prevalence increases PPV and decreases NPV; sensitivity and specificity are unchanged.","Prevalência sobe VPP."],["1lalgwskp","What happens to sensitivity and specificity if the cutoff for a positive test is lowered (more inclusive)?","Sensitivity increases (fewer FN), specificity decreases (more FP), NPV increases, PPV decreases.","Mais sensível, menos específico."],["27fbmrt80","What is a positive likelihood ratio?","Sensitivity / (1 - specificity). How much a positive test increases the odds of disease.","Sens / (1 - esp)."],["7e3sa310z","What is a negative likelihood ratio?","(1 - sensitivity) / specificity. How much a negative test decreases the odds of disease.","(1 - sens) / esp."],["jlknpmnv3","What LR values are considered strong evidence?","LR+ > 10 strongly rules in disease; LR- < 0.1 strongly rules out disease.","Acima de 10 ou abaixo de 0,1."],["1hnrvi2pa","What is a receiver operating characteristic (ROC) curve?","Plot of sensitivity (y) vs 1 - specificity (x) across cutoffs; area under the curve shows overall test accuracy.","Sensibilidade vs falso positivo."],["1110bvsfv","What does an ROC area under the curve of 0.5 mean?","The test performs no better than chance.","Teste inútil."],["1ycoj7v19","Formula for incidence?","New cases in a time period / population at risk during that period.","Casos novos / população em risco."],["1vshkou9n","Formula for prevalence?","Existing cases at a point in time / total population at that time.","Casos existentes / população."],["1rxdn7gz4","Relationship between prevalence and incidence for chronic diseases?","Prevalence ≈ incidence x average disease duration.","Prevalência = incidência x duração."],["19yel25m2","What happens to prevalence if a new treatment prolongs survival without curing disease?","Prevalence increases (incidence unchanged).","Prevalência aumenta."],["1nsddtwku","What happens to prevalence if a new vaccine reduces new cases?","Incidence and prevalence both decrease.","Prevalência cai com o tempo."],["m51x218yd","Formula for relative risk (RR)?","[a/(a+b)] / [c/(c+d)]: risk of disease in exposed divided by risk in unexposed.","Risco expostos / risco não expostos."],["1yuqjym1l","Formula for odds ratio (OR)?","(a x d) / (b x c): odds of exposure among cases divided by odds of exposure among controls.","(a x d) / (b x c)."],["118ox3d1a","When does the odds ratio approximate the relative risk?","When the disease is rare (low prevalence).","Doença rara."],["ouonsv1go","Formula for attributable risk?","Risk in exposed minus risk in unexposed: a/(a+b) - c/(c+d).","Risco expostos menos não expostos."],["btfjhdn43","Formula for relative risk reduction?","(Risk in control - risk in treated) / risk in control, or 1 - RR.","1 - RR."],["s4106a1q3","Formula for absolute risk reduction?","Risk in control group minus risk in treatment group (ARR).","Risco controle menos tratado."],["60o7e218s","Formula for number needed to treat?","1 / absolute risk reduction.","1 / RRA."],["rxrxvu1tp","Formula for number needed to harm?","1 / attributable risk (absolute risk increase).","1 / aumento de risco."],["19anp7uer","If an outcome happens in 10% of placebo patients and 6% of treated patients, what is the NNT?","ARR = 0.04; NNT = 1/0.04 = 25.","NNT = 25."],["10pa47a1y","What is case fatality rate?","Deaths from a disease / number of people with the disease (in a period).","Mortes entre os doentes."],["12keo854i","What is mortality rate?","Deaths in a period / total population.","Mortes na população."],["13qoe75wu","What is attributable risk percent?","(Risk in exposed - risk in unexposed) / risk in exposed, or (RR - 1)/RR.","Fração do risco pela exposição."],["100xfd011","What does a relative risk of 1 mean?","No association between exposure and disease.","Sem associação."],["bivu6mc2e","What does an RR less than 1 mean?","The exposure is associated with reduced risk (protective).","Fator protetor."],["1f2dqa813","What is a confidence interval?","Range of values likely to contain the true population parameter (e.g., 95%).","Faixa provável do valor real."],["1wxfwdvr4","When is an RR or OR statistically significant using its 95% CI?","When the confidence interval does not include 1.","IC não inclui 1."],["tdulskarq","When is a difference between means statistically significant using its 95% CI?","When the confidence interval does not include 0.","IC não inclui 0."],["1jlk40s11","How does increasing sample size affect a confidence interval?","Narrows it (more precision).","IC mais estreito."],["19j1v5i1b","What is the null hypothesis?","Hypothesis of no difference or no association in the population.","Sem diferença."],["1e2hslz6c","What is a type I error (alpha)?","Rejecting a true null hypothesis: stating there is an effect when there is none (false positive).","Falso positivo."],["lq4piwg74","What is a type II error (beta)?","Failing to reject a false null hypothesis: stating there is no effect when there is one (false negative).","Falso negativo."],["1pdt1imhd","What is statistical power?","1 - beta: probability of rejecting the null hypothesis when it is false (detecting a true effect).","Detectar efeito real."],["17afun7gy","What increases statistical power?","Larger sample size, larger expected effect size, higher precision (less variance), larger alpha.","Amostra maior, efeito maior."],["1ihcf7pnl","What is the p-value?","Probability of obtaining results at least as extreme as observed if the null hypothesis were true.","Chance do acaso."],["dgjo6qwr8","What does p < 0.05 typically mean?","The result is statistically significant at alpha 0.05; reject the null hypothesis.","Significativo."],["1don73o1t","Does statistical significance mean clinical significance?","No; a small, clinically unimportant difference can be statistically significant with a large sample.","Não necessariamente."],["68mqf51iq","Which test compares the means of two groups?","t-test.","Teste t."],["1kb8obv1g","Which test compares the means of three or more groups?","ANOVA (analysis of variance).","ANOVA."],["1lue2si1g","Which test compares proportions or percentages of categorical outcomes?","Chi-square test (Fisher exact test for small samples).","Qui-quadrado."],["135xtl2fk","What does the Pearson correlation coefficient (r) measure?","Strength and direction of a linear relationship between two continuous variables, from -1 to +1.","Força da relação linear."],["ybmb8eb1d","What does the coefficient of determination (r^2) represent?","Proportion of variance in one variable explained by the other.","Variação explicada."],["18mcskn1e","Does correlation imply causation?","No; correlation only indicates association.","Não."],["1xgrkinq6","Which statistical test is used for paired data from the same subjects before and after treatment?","Paired t-test.","Teste t pareado."],["bjgcxm1rd","What is the standard deviation vs standard error of the mean?","SD: variability of individual data points. SEM = SD / square root of n: precision of the sample mean estimate.","DP = dispersão; EP = DP/√n."],["e239v511p","In a normal distribution, what percentage lies within 1, 2, and 3 SD?","About 68%, 95%, 99.7%.","68%, 95%, 99,7%."],["djp33315f","In a positively skewed distribution, what is the order of mean, median, mode?","Mean > median > mode (tail on the right).","Média > mediana > moda."],["1vb77io1a","In a negatively skewed distribution, what is the order?","Mean < median < mode (tail on the left).","Média < mediana < moda."],["1iyi4fgve","Which measure of central tendency is least affected by outliers?","Median.","Mediana."],["1tmh2i9hh","What is a bimodal distribution?","A distribution with two peaks, suggesting two distinct populations.","Dois picos."],["qu5m0j5z0","What is selection bias?","Nonrandom sampling or treatment allocation leading to a study population that is not representative.","Amostra não representativa."],["yjp4wv1r9","What is Berkson bias?","Selection bias from studying hospitalized patients, who differ from the general population.","Viés de hospital."],["1acwak5ll","What is attrition bias?","Differential loss to follow-up between groups, biasing results.","Perda de seguimento."],["17xsv871e","What is the healthy worker effect?","Working populations are healthier than the general population, underestimating risks of exposure.","Trabalhador é mais saudável."],["13kgs2uvx","What is recall bias?","Awareness of disease changes recall of past exposures, common in case-control studies.","Memória seletiva."],["zshgs9fkm","What is measurement bias?","Information is gathered in a way that distorts it (e.g., faulty instruments).","Medição incorreta."],["zqy9ow1gk","What is the Hawthorne effect?","Subjects change behavior because they know they are being observed.","Muda por ser observado."],["1td0wu61i","What is procedure bias?","Subjects in different groups are not treated the same (e.g., more attention to the treatment group).","Grupos tratados diferente."],["1bs9c9814","What is observer-expectancy bias (Pygmalion effect)?","Researcher's belief in the treatment influences the outcome; reduced by blinding.","Expectativa do avaliador."],["jlbdafqxv","What is lead-time bias?","Early detection appears to increase survival, but only makes the diagnosis earlier without changing outcome.","Diagnóstico precoce parece sobrevida."],["1y9bkx1cd","How is lead-time bias minimized?","Measure back-end survival (mortality rates) rather than survival from diagnosis.","Comparar mortalidade."],["ijvhvbrun","What is length-time bias?","Screening preferentially detects slowly progressing diseases, making screening seem to improve survival.","Pega doença lenta."],["yipgv21mx","What is confounding?","A factor related to both exposure and outcome distorts the true relationship.","Terceira variável confunde."],["1i3lvy8g9","How is confounding reduced?","Randomization, matching, restriction, stratified analysis, multivariable adjustment, crossover design.","Randomizar, parear, estratificar."],["1h1ulfeph","What is effect modification?","The effect of an exposure on an outcome differs depending on a third variable (a real biologic interaction, not bias).","Efeito muda por subgrupo."],["1cgnvpg13","How do you distinguish confounding from effect modification?","Confounding: stratified estimates are similar to each other but differ from the crude estimate. Effect modification: stratified estimates differ from each other.","Confusão some ao estratificar."],["mxhjcf19a","What is publication bias?","Studies with positive results are more likely to be published.","Só resultado positivo é publicado."],["1jwxz2h1u","What is the purpose of blinding?","Reduces observer and subject bias; double-blind means neither subjects nor investigators know the assignment.","Reduz viés de expectativa."],["1077snz1g","What is the purpose of intention-to-treat analysis?","Analyzes participants in the group to which they were randomized, preserving randomization and reducing bias.","Analisa como randomizado."],["1jxd4kkj8","What is per-protocol analysis?","Analyzes only patients who completed the treatment as assigned; can overestimate efficacy.","Só quem cumpriu o protocolo."],["1sgmr9c1u","What is primary prevention?","Preventing disease before it occurs (e.g., vaccination, seat belts).","Evitar a doença."],["um2ira1bw","What is secondary prevention?","Early detection of disease to reduce morbidity (e.g., screening Pap smear, mammography).","Detecção precoce."],["15w9eu01b","What is tertiary prevention?","Reducing complications of established disease (e.g., rehabilitation, insulin for diabetes complications).","Reduzir sequelas."],["1gb2rv2rf","What is quaternary prevention?","Avoiding unnecessary or excessive medical interventions (overmedicalization).","Evitar excesso médico."],["ck5vrwpa5","What makes a disease appropriate for screening?","Significant burden, detectable preclinical phase, effective early treatment, acceptable test with good sensitivity, cost-effective.","Comum, grave, tratável, teste bom."],["9ifcnb14b","What is herd immunity?","Indirect protection of unvaccinated individuals when a large enough portion of a population is immune.","Proteção pela maioria vacinada."],["1aowxj1f5","What is the basic reproduction number (R0)?","Average number of secondary cases from one case in a fully susceptible population.","Contágios por caso."],["gnv4171uu","What is an epidemic vs endemic vs pandemic?","Endemic: constant baseline presence. Epidemic: cases above expected. Pandemic: epidemic spread across countries/continents.","Surto, constante, mundial."],["122v7b417","What is attack rate?","Number of people who become ill / number exposed during an outbreak.","Casos / expostos."],["whtj7b1oj","What is the difference between efficacy and effectiveness?","Efficacy: performance under ideal trial conditions. Effectiveness: performance in real-world settings.","Ideal vs mundo real."],["1mdq64zy6","What is precision (reliability) of a test?","Consistency and reproducibility of results; reduced by random error.","Repetibilidade."],["1vbsy3e13","What is accuracy (validity) of a test?","Closeness to the true value; reduced by systematic error (bias).","Proximidade da verdade."],["kkt7x62ae","How does random error vs systematic error affect results?","Random error decreases precision; systematic error decreases accuracy.","Aleatório reduz precisão; sistemático, acurácia."],["fjexlac3z","What is interrater reliability and how is it measured?","Agreement between observers; measured by the kappa statistic.","Concordância entre avaliadores; kappa."],["lz2hsd1ld","What does a kappa of 0 vs 1 mean?","0 = agreement no better than chance; 1 = perfect agreement.","Acaso vs perfeita."],["a5lpwyqe7","What is the Bradford Hill criteria's 'dose-response' element?","Greater exposure is associated with greater risk, supporting causality.","Mais dose, mais efeito."],["70g9sy7db","Name some Bradford Hill criteria for causation.","Temporality (essential), strength, dose-response, consistency, plausibility, specificity, coherence, experiment, analogy.","Força, consistência, temporalidade."],["x0rpsq1mx","What is the only absolutely necessary Bradford Hill criterion?","Temporality: exposure must precede outcome.","Temporalidade."],["zw5gylomw","What is the purpose of a funnel plot in meta-analysis?","Detects publication bias by plotting effect size against study size; asymmetry suggests bias.","Detecta viés de publicação."],["jklrrpnk3","What is a forest plot?","Displays effect sizes and confidence intervals of individual studies and the pooled estimate in a meta-analysis.","Resume estudos e IC."],["zpepvi1kx","What is a Kaplan-Meier curve?","Shows probability of survival (or event-free status) over time in groups.","Sobrevida ao longo do tempo."],["18nzdwu1o","What is a hazard ratio?","Ratio of event rates over time between groups (from survival analysis, e.g., Cox model).","Risco instantâneo comparado."],["tq9j7k148","What is regression to the mean?","Extreme values on first measurement tend to be closer to average on repeat measurement.","Extremos voltam à média."],["1eakjlsbf","What is a noninferiority trial?","Tests whether a new treatment is not unacceptably worse than an established one (within a margin).","Não é pior que o padrão."],["eprd84quj","What is the purpose of a placebo control?","Accounts for placebo effects and natural history, isolating the effect of the treatment.","Isola efeito real."],["100h11717","What is quality-adjusted life year (QALY)?","Measure combining length and quality of life, used in cost-effectiveness analysis.","Anos ajustados pela qualidade."],["yxaob012a","What is the number needed to screen?","Number of people who must be screened to prevent one adverse outcome.","1 / redução absoluta."],["hjl4681ys","What is the purpose of stratified sampling?","Ensures representation of subgroups by sampling within each stratum.","Representar subgrupos."],["1393ppz14","What is a nested case-control study?","A case-control study performed within an existing cohort.","Caso-controle dentro de coorte."],["ztu1ww1m1","What is the difference between a cohort and a case-control in terms of the starting point?","Cohort starts with exposure status; case-control starts with disease status.","Exposição vs doença."],["ndy64gw5f","Which study design is best for rare diseases?","Case-control study.","Caso-controle."],["10wlten86","Which study design is best for rare exposures?","Cohort study.","Coorte."],["1lry7ea1g","Which study design can measure incidence directly?","Cohort study (and RCT).","Coorte."],["p2f2mc784","What is a case series?","Descriptive report of several patients with a similar diagnosis or treatment; no control group.","Descrição de casos."],["lzydc7veg","What is a sentinel event in quality improvement?","Unexpected occurrence involving death or serious physical or psychological injury; requires root cause analysis.","Evento grave evitável."],["10gbdzyet","What is a root cause analysis?","Retrospective, systematic method to identify underlying causes of an adverse event, focusing on systems rather than individuals.","Busca a causa do erro."],["1hyrk1pvn","What is the Swiss cheese model of error?","Errors occur when holes (weaknesses) in multiple layers of defense line up.","Falhas alinhadas causam erro."],["1q0y3djoi","What is a near miss?","An unplanned event that could have caused harm but did not reach the patient or was caught.","Quase erro."],["1b6hgn91t","What is the PDSA cycle?","Plan-Do-Study-Act: iterative model for testing quality improvement changes.","Planejar, fazer, checar, agir."],["pabks0q1l","What are process vs outcome vs balancing measures in QI?","Process: whether steps are performed. Outcome: effect on patients. Balancing: unintended consequences elsewhere.","Processo, resultado, equilíbrio."],["12gufqcfm","What is the difference between active and latent errors?","Active: at the point of care (e.g., wrong dose given). Latent: system flaws that set up errors (e.g., similar drug packaging).","Erro direto vs do sistema."],["80weva1qn","What is anchoring bias in clinical reasoning?","Relying too heavily on initial information and failing to adjust with new data.","Preso à primeira impressão."],["aei0zmyct","What is availability bias?","Judging likelihood based on how easily examples come to mind (e.g., recent memorable case).","Lembra o mais recente."],["rgcm4m2sk","What is premature closure?","Accepting a diagnosis before it is fully verified.","Para cedo de investigar."],["1vdu9kb1l","What is framing bias?","Being influenced by the way information is presented.","Depende de como é apresentado."],["14zc8j818","What is the 'second victim' phenomenon?","Healthcare workers involved in an adverse event experience emotional distress.","Profissional traumatizado pelo erro."],["1g5swy6xe","What is a standardized mortality ratio?","Observed deaths / expected deaths in a population, adjusting for age or other factors.","Mortes observadas / esperadas."],["nnmld416i","What is the purpose of age adjustment?","Allows comparison of rates between populations with different age structures.","Comparar populações."],["yxlw9g11q","What is a z-score?","Number of standard deviations a value is from the mean.","Desvios da média."],["1g7arpzzr","What is the difference between nominal, ordinal, interval, and ratio variables?","Nominal: categories without order. Ordinal: ordered categories. Interval: equal intervals, no true zero. Ratio: equal intervals with true zero.","Tipos de variável."],["1inzv3w7y","Which test is used for ordinal or non-normally distributed data comparing two groups?","Nonparametric tests such as the Mann-Whitney U (independent) or Wilcoxon signed-rank (paired).","Mann-Whitney."],["2or9of1y6","What is the formula for pretest odds and post-test odds?","Pretest odds = probability / (1 - probability). Post-test odds = pretest odds x likelihood ratio.","Odds = p / (1 - p); x LR."],["1qp2rcr2h","What is the effect of a highly sensitive test when used in a low-prevalence population?","High NPV, but many false positives (low PPV).","Muitos falsos positivos."],["kev11puvw","What is cutoff-based tradeoff: increasing specificity?","Fewer false positives and higher PPV, but more false negatives and lower sensitivity.","Menos falso positivo, mais falso negativo."],["5bpgry464","What does a 2x2 table cell 'b' represent in exposure-disease studies?","Exposed and without disease.","Expostos sem doença."],["1d29r511n","What is the difference between relative risk and attributable risk in public health terms?","RR measures strength of association; AR measures excess risk due to exposure (public health impact).","RR vs impacto absoluto."]]},{"name":"Ethics","cards":[["1s05smu1f","What is the principle of autonomy?","Obligation to respect patients as individuals and honor their preferences, including the right to refuse care.","Respeitar a escolha do paciente."],["16hk0yp1e","What is the principle of beneficence?","Physicians have a duty to act in the patient's best interest.","Agir pelo bem do paciente."],["1tz5947ob","What is the principle of nonmaleficence?","Do no harm; the benefits of an intervention must outweigh the risks.","Não causar dano."],["1hcfm8r19","What is the principle of justice?","Treating patients fairly and equitably; distributing resources fairly.","Distribuir recursos com equidade."],["1s98rq2kf","What are the four components of informed consent?","Disclosure (nature, purpose, risks, benefits, alternatives, including no treatment), understanding, capacity, and voluntariness.","Informar, explicar, entender, decidir livremente."],["12hultzbn","What are exceptions to informed consent?","Emergency situations with implied consent, patient waiver, therapeutic privilege (rare), and lack of decision-making capacity (use surrogate).","Emergência, incapacidade, renúncia."],["1m2ccld1s","What is therapeutic privilege?","Withholding information when disclosure would severely harm the patient or undermine decision-making capacity; rarely appropriate.","Omitir informação que causaria dano."],["1reghic60","What is decision-making capacity?","A clinical determination that a patient can make a specific medical decision: understands, appreciates, reasons, and communicates a choice.","Capacidade de decidir."],["eaz1qq1qk","Who determines decision-making capacity vs competence?","Capacity is determined by a physician for a specific decision. Competence is a legal determination made by a judge.","Médico avalia capacidade; juiz, competência."],["bm78zml7i","Does a psychiatric diagnosis automatically mean a patient lacks capacity?","No; capacity is decision-specific and can be present despite mental illness.","Não."],["cbl1gepvu","What should be done if a patient with capacity refuses a life-saving treatment?","Respect the refusal after ensuring informed understanding, exploring reasons, and addressing concerns.","Respeitar a recusa."],["15drxt015","When can minors consent to treatment without parental consent?","Emergencies, sexual health (contraception, STIs, prenatal care in many states), substance use treatment, and emancipated minors.","Gravidez, IST, drogas, contracepção."],["y3sv5q1kj","What makes a minor emancipated?","Being married, self-supporting, in the military, or having children (varies by state).","Casado, independente, militar ou pai."],["1dv2ppyht","Can a minor's parents force abortion or contraception?","No; and many states require parental notification or consent for abortion in minors, with judicial bypass available.","Não."],["hydp5v5km","What should be done if parents refuse life-saving treatment for their child (e.g., blood transfusion)?","In an emergency, treat the child; physicians may seek a court order. Parents cannot refuse life-saving treatment for a minor.","Tratar e acionar a justiça."],["1y04ch81l","Can parents refuse vaccination for their children?","Physicians should explore concerns and educate; parents generally may refuse routine vaccinations, but this is not life-threatening emergency care.","Sim, em geral."],["1w7oq0az2","What is an advance directive?","Instructions given by a patient in anticipation of losing capacity to make decisions.","Instruções antecipadas."],["151k4ue1k","What is a living will?","Written advance directive describing treatments the patient wishes to receive or refuse if incapacitated.","Testamento vital."],["h4lwdkjnb","What is a durable power of attorney for health care?","Patient designates a surrogate to make medical decisions if the patient loses capacity.","Procurador de saúde."],["1ldfyw91i","What is a POLST form?","Physician orders for life-sustaining treatment: actionable medical orders for seriously ill patients, transferable across settings.","Ordens médicas de fim de vida."],["3fp5ga1qe","Order of surrogate decision makers when no designated agent exists?","Spouse, adult children, parents, adult siblings, other relatives (varies by state).","Cônjuge, filhos, pais, irmãos."],["1j9ltzi45","What standard should a surrogate use when making decisions?","Substituted judgment (what the patient would have wanted); if unknown, the patient's best interest.","Julgamento substituto."],["ndaoem1fn","What is a Do Not Resuscitate (DNR) order?","Prohibits CPR and advanced cardiac life support; other treatments may continue unless specified.","Não reanimar."],["csdmv71wm","Is withdrawing life support ethically different from withholding it?","No; they are ethically equivalent.","Não."],["w5zjez1ok","What is the principle of double effect in palliative care?","Treatment intended to relieve suffering (e.g., opioids) is acceptable even if it may hasten death as an unintended effect.","Intenção boa com efeito colateral."],["5yr5be1us","Is physician-assisted death legal everywhere in the US?","No; it is legal only in some states, with strict criteria (terminally ill, capable adult self-administers medication). Euthanasia is illegal in the US.","Não."],["1y5sdst15","What is the difference between euthanasia and physician-assisted death?","Euthanasia: physician administers the lethal medication. Physician-assisted death: physician prescribes, patient self-administers.","Médico aplica vs paciente toma."],["1261jndu9","What is the ethical approach to a patient requesting a non-indicated treatment?","Physicians are not obligated to provide treatments that are futile or not medically indicated; explain and explore concerns.","Não precisa fornecer."],["1eqq27b2j","What is medical futility?","Treatment with no reasonable chance of achieving the patient's goals; physicians may decline to provide it.","Tratamento sem benefício."],["1c4fd0cbf","What is confidentiality?","Respecting patient privacy and autonomy by not disclosing health information without consent.","Sigilo médico."],["1w9o9ik18","When can confidentiality be broken?","Potential harm to others is serious, there is a likelihood of harm, no other means to warn/protect, and steps can prevent harm (e.g., Tarasoff duty).","Risco a terceiros ou notificação."],["1d6znh5x8","What is the Tarasoff decision?","Physicians have a duty to protect (warn and/or take steps to protect) a third party when a patient poses a serious threat of violence.","Dever de proteger terceiros."],["1f68vh61u","Which infectious diseases must be reported to public health?","Notifiable diseases such as HIV (in many states), TB, syphilis, gonorrhea, chlamydia, hepatitis, measles, and others.","Doenças de notificação."],["13331pfnd","What should a physician do when a patient with epilepsy continues to drive?","Counsel the patient; reporting requirements vary by state; in some states physicians must report unsafe drivers.","Orientar e notificar se exigido."],["8gu6bi1s1","Is elder abuse reportable?","Yes; suspected elder abuse must be reported (mandatory in most states).","Sim."],["cdxqoeqpc","Is intimate partner violence mandatorily reportable?","Generally not (except in some states or with specific injuries); encourage patient to seek help, provide safety planning and resources.","Depende do estado."],["74xep86b7","How should you ask about intimate partner violence?","Privately, without the partner present, in a nonjudgmental way; screen all women of reproductive age.","Em particular, sem acompanhante."],["cln3851kp","What is the appropriate response to a gift from a patient?","Small gifts may be accepted if not inappropriate; decline large gifts or those that could influence care.","Aceitar se pequeno."],["11mj0ura4","What is the appropriate response to gifts from pharmaceutical companies?","Avoid gifts that may influence prescribing; small educational items of modest value may be acceptable under guidelines.","Recusar presentes relevantes."],["6zwv2v1bc","What should a physician do if a colleague appears impaired?","Report to the appropriate authority (e.g., supervisor, physician health program, licensing board) to protect patients.","Comunicar a autoridade."],["t7bd0c12n","What should a physician do after making a medical error?","Disclose the error honestly to the patient, apologize, explain the plan to correct it, and report through institutional systems.","Revelar o erro."],["1n08daorj","What should you do if a patient asks you to keep a secret from their family?","Respect the patient's confidentiality unless there is a legal or safety exception.","Respeitar o paciente."],["mhmq9b191","What should you do if a family asks you not to tell a patient a diagnosis?","Explore the family's reasons, but the patient has the right to know; assess the patient's wishes about information.","Explorar o motivo; paciente decide."],["axgnb2509","How should a physician respond to a patient's request to see their medical records?","Patients have a right to access their records; facilitate access (rare exceptions).","Fornecer o prontuário."],["kj1ouei5y","What is the approach to a patient who is noncompliant?","Explore reasons nonjudgmentally (cost, side effects, beliefs), collaborate on a plan.","Entender o motivo."],["164wvcm19","What is the approach when a patient requests a different physician because of the doctor's characteristics?","Respect autonomy when feasible; avoid compromising care; address discriminatory requests per institutional policy.","Pode atender; explorar o motivo."],["vl487e1h8","What is the approach to romantic relationships with patients?","Never appropriate with current patients; relationships with former patients are discouraged and may be inappropriate depending on circumstances.","Proibido."],["1g1m1jryy","How should a physician handle a patient who is angry or upset?","Acknowledge feelings, listen, apologize when appropriate, avoid becoming defensive.","Reconhecer a emoção."],["flapuj1uz","How should you deliver bad news (SPIKES)?","Setting, Perception, Invitation, Knowledge, Emotions/Empathy, Strategy and Summary.","Protocolo SPIKES."],["1x14z0s1f","What is the approach to a patient who wants to try alternative medicine?","Explore beliefs, discuss benefits and risks, ensure no harmful interactions, continue to provide care.","Discutir sem julgar."],["11ijxtkyi","What is the approach to a patient with limited English proficiency?","Use a professional medical interpreter, not family members (especially not children).","Intérprete profissional."],["m6ijy61rt","What is the role of a hospital ethics committee?","Provides consultation when ethical conflicts arise among patients, families, and clinicians.","Consultoria em dilemas."],["no60uf1r5","What is the approach to a patient requesting antibiotics for a viral infection?","Explain why antibiotics are not indicated, address concerns and symptoms, avoid prescribing unnecessary medications.","Explicar e não prescrever."],["wjamz51cm","What is the approach to a patient requesting euthanasia when it is illegal?","Explore the reasons (depression, pain, fear of burden), optimize palliative care, and do not provide euthanasia.","Explorar o motivo; recusar."],["5ylzzk1c5","How should physicians respond when a patient wants to disclose a terminal diagnosis to family themselves?","Respect the patient's wishes regarding who is told and when.","Respeitar e apoiar."],["f53u8rh3f","What is HIPAA?","US law protecting the privacy and security of patient health information; allows disclosure for treatment, payment, operations, and certain public health needs.","Lei de privacidade de saúde."],["gqbrzb8fx","When can protected health information be shared without patient consent?","For treatment, payment, health care operations, public health reporting, law enforcement in specific situations, and to prevent serious threats.","Tratamento, pagamento, saúde pública."],["1i401u7mz","What is the minimum necessary standard in HIPAA?","Only share the minimum information necessary for the purpose.","Compartilhar só o necessário."],["ywfy4agl3","What is EMTALA?","Federal law requiring hospitals to provide screening and stabilizing treatment for emergencies regardless of ability to pay.","Atender emergências sempre."],["1s7r4he1y","What is a conflict of interest?","When a physician's personal interests (financial or other) could compromise professional judgment; must be disclosed and managed.","Interesse que interfere."],["1vsndx41k","What should a physician do if asked to participate in a procedure they object to morally?","Physicians may decline but must refer the patient to another provider and not obstruct access in emergencies.","Encaminhar a outro médico."],["1sbmlz313","What should be done when an adult patient refuses a blood transfusion for religious reasons?","Respect the refusal if the patient has capacity and is informed; consider alternatives (e.g., erythropoietin, cell salvage).","Respeitar a recusa."],["iev69a1mn","Can a pregnant woman refuse a cesarean section?","Yes; a competent pregnant patient may refuse treatment even if it may harm the fetus.","Sim."],["11zxbi41l","What is the approach to an elderly patient with dementia who wants to go home against advice?","Assess capacity for that specific decision; if lacking, use surrogate and best interest; if capable, respect choice while ensuring safety plan.","Avaliar capacidade."],["ew0pdsowd","What is the role of an institutional review board (IRB)?","Reviews and monitors research involving human subjects to protect their rights and welfare.","Comitê de ética em pesquisa."],["h04kow1tz","What is required for ethical human research?","Informed consent, favorable risk-benefit ratio, fair subject selection, independent review, confidentiality, ability to withdraw.","Consentimento e revisão ética."],["17yljlcjk","What is the approach to a request for a chaperone during sensitive exams?","Offer a chaperone for intimate exams regardless of physician or patient gender; honor patient requests.","Oferecer acompanhante."],["5lm35s1c5","What should a physician do if they are unable to provide care because of a conflict?","Arrange transfer of care to another qualified physician; do not abandon the patient.","Transferir o cuidado."],["1hmta4iou","What is patient abandonment?","Ending the physician-patient relationship without reasonable notice or arranging for continuing care.","Abandono do paciente."],["1agn8gmzw","How should a physician end a physician-patient relationship?","Give adequate written notice, provide care in the interim, and help transfer to another physician.","Avisar e garantir transição."],["12i34q71r","What is the approach to a request from a colleague to treat their family member?","Treating family members is generally discouraged except in emergencies or minor problems.","Evitar tratar família."],["1hnj3tc5a","What should a physician do if asked by police for patient information?","Generally require patient consent or a court order/warrant, unless reporting is legally required or there is an imminent threat.","Só com ordem ou exigência legal."],["10jxamo1s","Can a physician test a patient for HIV without consent after a needlestick injury?","Rules vary; generally consent is required, but some states allow testing of source patient's blood in specific circumstances.","Depende da lei; pedir consentimento."],["11gq2nd73","How should HIV test results be shared with partners?","Encourage the patient to notify partners; partner notification via public health may be used; physicians may notify if patient refuses, depending on state law.","Paciente informa; médico se recusar."],["89ou5sfw3","What is the role of shared decision making?","Patient and clinician collaborate, combining evidence with patient values and preferences.","Decisão compartilhada."],["1nunjkkqh","What are open-ended questions used for?","Gathering information and encouraging patients to tell their story (e.g., 'Tell me about your pain').","Explorar a visão do paciente."],["6k3b0hdfr","What is the best way to respond to a patient who cries?","Pause, acknowledge emotions, offer support (e.g., 'I can see this is difficult').","Ficar em silêncio e acolher."],["1fjusxmww","What is motivational interviewing?","A counseling approach that helps patients explore ambivalence and strengthen motivation for behavior change.","Entrevista motivacional."],["rky0w475k","Stages of change (transtheoretical model)?","Precontemplation, contemplation, preparation, action, maintenance (and relapse).","Estágios de mudança."],["1r03fmh2s","What intervention is best for a patient in precontemplation?","Raise awareness of risks and benefits of change without pressure.","Informar sem pressão."],["x8d32izbz","What is the approach to a patient who is suicidal?","Assess risk (plan, intent, means), ensure safety (hospitalize if high risk, even involuntarily), remove access to means.","Avaliar risco e proteger."],["19j6lkd1x","When is involuntary psychiatric commitment allowed?","When a person is an imminent danger to self or others, or gravely disabled due to mental illness.","Risco iminente a si ou outros."],["19e3qly4v","What is the approach when a patient asks the physician's opinion about a decision?","Provide an honest recommendation while respecting the patient's ultimate decision.","Ajudar com base nos valores."],["8otgu21ri","How should a physician respond to a patient who requests a specific test that is not indicated?","Explore the reason, explain why it is not indicated; physicians are not required to order unnecessary tests.","Explicar e não pedir."],["l709c91l4","What is the ethical problem with prescribing for oneself?","Lack of objectivity; especially inappropriate for controlled substances.","Falta de objetividade."],["12np29j1f","What should you do if you witness a colleague committing fraud or unethical behavior?","Report it through appropriate channels.","Comunicar a quem de direito."],["14wdixh1v","What is the appropriate response if a patient offers you a large monetary gift?","Politely decline to avoid compromising the relationship or creating conflict.","Recusar."],["14b1wtb1u","What is the most appropriate first step when a patient seems to misunderstand risks before a procedure?","Re-explain in plain language and confirm understanding (teach-back).","Explicar de novo."],["td0ga01h8","What is teach-back method?","Asking patients to repeat information in their own words to confirm understanding.","Paciente repete o que entendeu."],["1qh90ur6l","How should a physician respond to a patient with low health literacy?","Use plain language, visual aids, teach-back; avoid medical jargon.","Linguagem simples."],["14jfxoh1o","Can a patient's family override the patient's advance directive?","No; a valid advance directive reflects the patient's wishes and takes precedence.","Não."],["1yj4keq19","What should be done if there is no advance directive or surrogate for an incapacitated patient in an emergency?","Provide emergency treatment under implied consent.","Tratar no melhor interesse."],["19698131o","What is the approach to a child who requests confidentiality about sexual activity?","Many sexual health services are confidential for minors; encourage communication with parents while respecting legal confidentiality.","Manter sigilo."],["i5q1yw19x","Is parental consent required for a minor's contraception in the US?","Generally no (varies by state); minors can usually consent to contraception and STI treatment.","Não."],["gwpfjitw4","What is the main ethical concern with using family members as interpreters?","Breach of confidentiality, inaccurate translation, and inhibition of disclosure.","Erros e falta de sigilo."],["1agv59gfr","What should you do when you suspect a patient is a victim of human trafficking?","Speak to the patient alone, assess safety, provide resources; report per local law.","Avaliar com cuidado e oferecer ajuda."],["1kicido13","What does nonabandonment mean in end-of-life care?","Continued commitment to care for the patient, even when curative treatment stops.","Não abandonar."],["1o02n84rx","What is hospice care?","Palliative care for patients with a life expectancy of 6 months or less, focusing on comfort rather than cure.","Cuidado de conforto terminal."],["t1zz5c1e7","Is palliative care only for dying patients?","No; palliative care can be provided at any stage of serious illness, alongside curative treatment.","Não."],["3ue8u811d","What is brain death?","Irreversible cessation of all brain function including the brainstem; legally equivalent to death in the US.","Morte encefálica."],["x9c3h374k","Clinical criteria for brain death?","Coma, absent brainstem reflexes, apnea; exclusion of confounders (hypothermia, drugs, metabolic causes).","Coma, sem reflexos, apneia."],["hhf4rp54a","Who should approach families about organ donation?","Trained organ procurement organization staff, separate from the treating team, to avoid conflict of interest.","Equipe de captação."],["w94u0n17d","Can organs be procured from a donor after cardiac death?","Yes, donation after circulatory death is possible with consent after withdrawal of life support and declaration of death.","Sim."],["1snmjtelq","What is the ethical issue with physicians treating VIP patients differently?","May compromise care through deviations from standard protocols; treat according to standard of care.","Tratamento desigual."],["bg7x915r9","What is an important consideration when caring for incarcerated patients?","They retain rights to confidentiality and informed consent, and should receive appropriate care.","Mesmo padrão de cuidado."],["y44cvg1xm","What should a physician do when a patient makes a racist remark about staff?","Address the behavior, set boundaries, ensure care is not compromised, and support staff.","Apoiar a equipe."],["116enor1b","What is the principle of veracity?","Truthfulness: providing honest information to patients.","Dizer a verdade."],["15pav2p1k","What is the main ethical issue in direct-to-consumer genetic testing?","Potential for misinterpretation, lack of counseling, privacy concerns, and incidental findings.","Interpretar sem orientação."],["2kn46bs4s","What is an ethical consideration with incidental findings in research or imaging?","Patients should be informed of clinically significant findings with a plan for follow-up.","Planejar comunicação."],["10zp68x1w","What is the approach to a request for a sterilization procedure by a young patient?","Respect autonomy with thorough counseling about permanence; capacity and informed consent required.","Respeitar e informar."]]},{"name":"Physiology","cards":[["tsgahpvvc","What EEG waveform characterizes awake with eyes open?","Beta waves (highest frequency, lowest amplitude).","Ondas beta."],["1dxsrqz16","What EEG waveform characterizes awake with eyes closed?","Alpha waves.","Ondas alfa."],["1nxpkss8a","What EEG waveform characterizes stage N1 sleep?","Theta waves (light sleep, about 5% of sleep).","Ondas teta."],["1v97glk18","What EEG features characterize stage N2 sleep?","Sleep spindles and K complexes (about 45% of sleep; deeper sleep, when bruxism occurs).","Fusos e complexos K."],["1cwe3m6jb","What EEG waveform characterizes stage N3 sleep?","Delta waves (lowest frequency, highest amplitude); deepest non-REM sleep (slow-wave sleep).","Ondas delta."],["1d08tvc13","Which parasomnias occur during N3 sleep?","Sleepwalking, night terrors, bedwetting (enuresis).","Sonambulismo e terror noturno."],["1pqbhre6q","What EEG pattern is seen in REM sleep?","Beta waves (similar to wakefulness) with loss of muscle tone.","Beta com atonia."],["ui36a41au","What physiological changes occur during REM sleep?","Increased and variable pulse and blood pressure, penile/clitoral tumescence, dreaming, nightmares, rapid eye movements, loss of motor tone, increased brain O2 use.","Pulso variável, sonhos, ereção."],["1m4qqll5f","Mnemonic for EEG waveforms from awake to deep sleep?","At night, BATS Drink Blood: Beta (awake eyes open), Alpha (eyes closed), Theta (N1), Spindles (N2), Delta (N3), Beta (REM).","Mnemônico das ondas."],["h15lz0147","How often does REM sleep occur?","About every 90 minutes, with REM periods lengthening through the night.","A cada 90 minutos."],["x2wm5zjm0","Which brain structure controls REM sleep and which neurotransmitter starts it?","Pontine reticular formation (PPRF); acetylcholine is the principal neurotransmitter for REM.","Ponte; acetilcolina."],["1p76xuv1k","What controls the extraocular movements during REM sleep?","Paramedian pontine reticular formation (conjugate gaze center).","Formação reticular pontina."],["1e4gfsbvw","Which neurotransmitters reduce REM sleep?","Norepinephrine (and serotonin).","Noradrenalina e serotonina."],["9t2hqzprp","Which drugs decrease REM sleep and delta sleep?","Alcohol, benzodiazepines, barbiturates (decrease REM and N3).","Álcool, benzodiazepínicos, barbitúricos."],["1tcnewraj","Which drugs reduce N3 sleep and night terrors/sleepwalking?","Benzodiazepines.","Benzodiazepínicos."],["12cppehya","Which drug treats bedwetting (sleep enuresis)?","Desmopressin (oral formulation preferred); behavioral alarms are first line.","Desmopressina."],["clrhkmgct","Which drug is used for night terrors and sleepwalking (if needed)?","Benzodiazepines.","Benzodiazepínicos."],["sq18ob10d","What sleep changes occur in depression?","Decreased REM latency, increased REM early in night, decreased slow-wave sleep, early morning awakening.","REM precoce."],["1skrafd6z","What sleep changes occur in narcolepsy?","Short REM latency, sleep-onset REM periods.","REM no início do sono."],["zu82c089o","Which nucleus regulates circadian rhythm?","Suprachiasmatic nucleus (SCN) of the hypothalamus.","Núcleo supraquiasmático."],["1pz6vs314","What does the suprachiasmatic nucleus control?","Circadian rhythm of ACTH, prolactin, melatonin, nocturnal norepinephrine release.","Ritmo de ACTH, prolactina, melatonina."],["p3uhbtjmy","How does light regulate melatonin secretion?","Light stimulates retinal input to the SCN, which reduces norepinephrine release to the pineal gland, decreasing melatonin.","Luz reduz melatonina."],["1k5wzcnc7","What is melatonin synthesized from?","Serotonin (tryptophan derivative) in the pineal gland.","Serotonina."],["1azuiyo1w","What does a melatonin receptor agonist like ramelteon treat?","Insomnia (sleep-onset), with low abuse potential.","Insônia."],["epf5rc9ev","What neuropeptides promote wakefulness and are deficient in narcolepsy?","Orexin (hypocretin), produced in the lateral hypothalamus.","Orexina."],["8hcm5cslu","What are the main functions of the hypothalamus?","Thirst and water balance, adenohypophysis control, neurohypophysis release, hunger, autonomic regulation, temperature, sexual urges, circadian rhythms (TAN HATS).","Sede, fome, temperatura, hormônios."],["sgbstm8sb","What does the lateral hypothalamus do and what does destruction cause?","Hunger center; destruction causes anorexia and failure to thrive. Stimulated by ghrelin, inhibited by leptin.","Fome; lesão causa anorexia."],["1y2oz5hyx","What does the ventromedial hypothalamus do and what does destruction cause?","Satiety center; destruction (e.g., craniopharyngioma) causes hyperphagia and obesity. Stimulated by leptin.","Saciedade; lesão causa obesidade."],["16chysgz8","What does the anterior hypothalamus regulate?","Cooling and parasympathetic activity; lesion causes hyperthermia. Anterior = A/C (cooling).","Resfriamento."],["bcuumb1hu","What does the posterior hypothalamus regulate?","Heating and sympathetic activity; lesion causes poikilothermia. Posterior = heating.","Aquecimento."],["lug2p1140","What does the supraoptic nucleus make?","Mainly ADH (vasopressin).","ADH."],["phdod41ht","What does the paraventricular nucleus make?","Mainly oxytocin (also ADH, CRH, TRH).","Ocitocina."],["1qb9jec13","What does the arcuate nucleus make?","GnRH, GHRH, dopamine (inhibits prolactin).","GnRH, GHRH e dopamina."],["17hxwjq16","What is the role of the preoptic nucleus?","Thermoregulation and sexual behavior; releases GnRH. Failure of GnRH neuron migration causes Kallmann syndrome.","Temperatura e GnRH."],["1ja44qw13","What is the role of the organum vasculosum of the lamina terminalis (OVLT)?","Senses changes in osmolarity (lacks blood-brain barrier) and triggers thirst and ADH release.","Detecta osmolalidade."],["14rpesj1e","What is the role of the area postrema?","Chemoreceptor trigger zone in the 4th ventricle; responds to emetics (lacks blood-brain barrier).","Centro do vômito."],["19g4bbub3","What hormone stimulates hunger and where is it made?","Ghrelin, produced in the stomach; increased with sleep deprivation and Prader-Willi syndrome.","Grelina, estômago."],["1wlwfds26","What does leptin do and where is it made?","Decreases appetite; produced by adipose tissue, decreased in starvation and sleep deprivation.","Leptina, gordura."],["1n5kv18ei","What causes obesity in leptin deficiency or leptin receptor defects?","Lack of satiety signaling causing hyperphagia (congenital obesity).","Fome sem controle."],["z3vfjq1le","What is the role of endocannabinoids in appetite?","Increase appetite (the 'munchies').","Aumentam o apetite."],["6yuhax19r","What is the stress response pathway (HPA axis)?","Hypothalamus releases CRH, pituitary releases ACTH, adrenal cortex releases cortisol.","CRH, ACTH e cortisol."],["j5rylt1u2","What are the effects of acute stress via the sympathetic nervous system?","Increased heart rate, blood pressure, glucose, bronchodilation, pupil dilation (fight or flight).","Luta ou fuga."],["1avxch26h","What are the effects of chronic stress and elevated cortisol?","Immunosuppression, hyperglycemia, hypertension, muscle wasting, poor wound healing, mood changes.","Imunossupressão e hipertensão."],["79a6q51c8","What is the general adaptation syndrome?","Stages of response to stress: alarm, resistance, exhaustion.","Alarme, resistência, exaustão."],["1tvnb3rxz","How does sleep deprivation affect cognitive and metabolic function?","Impaired attention and memory, mood changes, increased appetite (ghrelin up, leptin down), insulin resistance.","Atenção e metabolismo pioram."],["1o1prsadn","How does sleep architecture change with age?","Decreased N3 (slow-wave) and REM sleep, more nighttime awakenings, earlier sleep timing.","Menos sono profundo."],["zuxz1916u","How long is the typical sleep cycle and how many per night?","About 90 minutes; 4-6 cycles per night.","90 minutos; 4 a 6 ciclos."],["19a0bcr1i","When is most N3 sleep concentrated?","In the first part of the night.","Início da noite."],["1w8cw3g1f","When is most REM sleep concentrated?","In the last part of the night (longer REM periods toward morning).","Fim da noite."],["ifn7td19o","What is the effect of benzodiazepine withdrawal on sleep?","Rebound insomnia and increased REM.","Insônia rebote."],["10sgdah1n","What is the effect of alcohol on sleep?","Initially sedating but causes REM suppression early and rebound REM with fragmented sleep later in the night.","Fragmenta o sono."],["1s4ao84je","What is the effect of stimulants (amphetamines, cocaine) on sleep?","Decreased total sleep and REM; withdrawal causes hypersomnia and vivid dreams.","Menos sono; depois hipersonia."],["namomy193","What is the purpose of sleep hygiene?","Behavioral practices to improve sleep: regular schedule, avoid caffeine/alcohol late, limit screens, use bed only for sleep and sex.","Hábitos para dormir melhor."],["s3dwku1l8","What is first-line treatment for chronic insomnia?","Cognitive behavioral therapy for insomnia (CBT-I).","Terapia cognitiva para insônia."],["c5m66e1ny","What neurotransmitter changes accompany wakefulness?","High norepinephrine (locus coeruleus), serotonin (raphe), histamine (tuberomammillary nucleus), acetylcholine, orexin.","Noradrenalina, serotonina, histamina."],["8svre9x8l","Why do first-generation antihistamines cause drowsiness?","They block central H1 receptors; histamine promotes wakefulness.","Bloqueiam H1 central."],["xaw5in1er","Where is the main source of norepinephrine in the brain?","Locus coeruleus (pons).","Locus ceruleus."],["kcg5zu1hj","Where is the main source of serotonin in the brain?","Raphe nuclei (brainstem).","Núcleos da rafe."],["1w4mfkmbn","Where is the main source of dopamine in the brain?","Ventral tegmentum and substantia nigra pars compacta (midbrain).","Área tegmentar e substância negra."],["1rj5ii7f7","Where is the main source of acetylcholine in the brain?","Nucleus basalis of Meynert (basal forebrain).","Núcleo basal de Meynert."],["pm81hkm1f","Where is GABA mainly produced?","Nucleus accumbens (and widely in inhibitory neurons).","Núcleo accumbens."],["jyujubrpo","Which neurotransmitter is decreased in Alzheimer disease?","Acetylcholine.","Acetilcolina."],["1symcsm1u","Which neurotransmitter is increased in anxiety?","Norepinephrine (and decreased GABA and serotonin).","Noradrenalina."],["cmhjxj18g","Which neurotransmitters are decreased in depression?","Norepinephrine, serotonin, and dopamine.","Noradrenalina, serotonina, dopamina."],["xumrjx1q3","Which neurotransmitter is increased in schizophrenia?","Dopamine (mesolimbic).","Dopamina."],["103e2kmp6","Which neurotransmitter changes occur in Parkinson disease?","Decreased dopamine, increased acetylcholine and serotonin.","Menos dopamina."],["lcuyty1b8","What is the sexual response cycle?","Excitement, plateau, orgasm, resolution.","Excitação, platô, orgasmo, resolução."],["1i6281amj","Which autonomic divisions mediate erection and ejaculation?","Erection: parasympathetic (point). Emission: sympathetic (squeeze). Ejaculation: visceral and somatic nerves (shoot). Point, squeeze, and shoot.","Apontar, apertar, disparar."],["vf1ysw171","What is the role of nitric oxide in erection?","NO increases cGMP, relaxing smooth muscle in the corpora cavernosa (enhanced by PDE5 inhibitors).","Aumenta GMPc."],["1vamqi716","What is the role of oxytocin in social behavior?","Promotes bonding, trust, and maternal behaviors; released during labor and breastfeeding.","Vínculo e confiança."],["1lx3u4n11","What is the physiological basis of thirst?","Increased plasma osmolality (osmoreceptors) and decreased blood volume (angiotensin II, baroreceptors) stimulate thirst.","Osmolalidade e volume."],["nda385f8f","What is the physiological effect of fever on the hypothalamus?","Pyrogens (IL-1, IL-6, TNF) increase prostaglandin E2 in the hypothalamus, raising the temperature set point.","Prostaglandina eleva o ponto."],["1rg0fyc1m","How do antipyretics like acetaminophen and NSAIDs reduce fever?","Inhibit COX in the CNS, decreasing PGE2 and lowering the hypothalamic set point.","Inibem COX central."]]}];
